defense.vulnerable_config:
# Node.js — no rate-limit, no lockout:
app.post('/api/v1/login', async (req, res) => {
  const { username, password } = req.body
  const user = await db.query('SELECT * FROM users WHERE username=?', [username])
  if (!user) return res.status(401).json({error: 'Invalid username'})  // VULN: username enumeration
  if (!bcrypt.compareSync(password, user.password_hash))
    return res.status(401).json({error: 'Invalid password'})  // VULN: different error = username valid
  res.json({ token: generateJWT(user) })  // VULN: unlimited attempts
})

# No WAF rule for auth endpoint
# No CAPTCHA
# No MFA required

defense.secure_config:
# Node.js — rate-limited, locked, constant-time response:
const rateLimit = require('express-rate-limit')
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 min window
  max: 10,                     // 10 attempts per IP per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many attempts, try again later' }
})
app.post('/api/v1/login', loginLimiter, async (req, res) => {
  const { username, password } = req.body
  const user = await db.query('SELECT * FROM users WHERE username=?', [username])
  // SAFE: same error and same timing whether username exists or not
  const valid = user && await bcrypt.compare(password, user.password_hash)
  if (!valid) {
    await bcrypt.hash('dummy', 10)  // constant-time even if user not found
    return res.status(401).json({ error: 'Invalid credentials' })  // generic message
  }
  // Check failed attempts and enforce lockout
  if (user.failed_attempts >= 5) return res.status(423).json({ error: 'Account locked' })
  res.json({ token: generateJWT(user) })
})

# WAF rule (nginx + ModSecurity or AWS WAF):
# Rate-limit /api/v1/login to 10 req/min per IP
# Block User-Agent containing 'ffuf' or 'python-requests' on auth endpoints
